head.script:
// 화면 리사이징

scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.elw.fn_searchCode();
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        // edt_SDate.text = cGetMinusDate2(vCurDate, 7);
        edt_SDate.setValue("20110101");
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        if (js_market === "1" || js_market === "2") {
            panel_mkt_gubun.hide();
        } else {
            panel_mkt_gubun.show("");
        }
        if (js_market === "1") {
            cmb_Commit_Tp_Cd_KOSPI.show("");
            cmb_Commit_Tp_Cd.hide();
            cmb_Commit_Tp_Cd_KOSPI.BindColVal = "A";
        } else {
            cmb_Commit_Tp_Cd_KOSPI.hide();
            cmb_Commit_Tp_Cd.show("");
            cmb_Commit_Tp_Cd.BindColVal = "A";
        }
        cmb_DELIST_REAL_INVSTG_RSN_CD.BindColVal = "A";
        cmb_Rslt.BindColVal = "A";
        // cmb_Remk.BindColVal = "A";
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20506.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        fn_GetPar = scwin.getParIsur;
        fn_SetPar = scwin.setParIsur;
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_ISUR_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20506.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20506.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF20506.gfm", SCREN_PROCS_TP_CD_07);
        // grd_Grid.GridToExcel("위원회별 심의내역 및 심사자료", "", "8");
        $c.data.downloadGridViewOffice(grd_Grid, "위원회별 심의내역 및 심사자료", "", 8, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20506.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20506.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20506.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20506.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20506.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20506.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20506.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (colid === "ATTACH_FILE_NM") {
            const vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
            const listEligtyProcsCd = dts_List.getCellData(row, "LIST_ELIGTY_PROCS_CD");
            let dtlSeq = dts_List.getCellData(row, "FILE_SEQ");
            const url = "/lstsrch/ULDSTF20506_FILE.gfm?BZ_PROCS_NO=" + vBzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + listEligtyProcsCd + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq;
            await $c.frame.CreateDialogFrame("FILE_ATTACH", url, "첨부파일 조회", 100, 100, 850, 450, "window");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20506.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            txb_ISUR_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20506.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_FileContents_onkeydown
 * @description txb_FileContents 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_FileContents_onkeydown = async function() {
    try {
        if (event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20506.txb_FileContents_onkeydown" });
    }
};

/**
 * @method
 * @name mgrd_Grid_OnLButtonDblClk
 * @description mgrd Grid On LButton Dbl Clk 처리
 * @param {*} type type
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} x x
 * @param {*} y y
 * @returns {void}
 * @hidden N
 */
scwin.mgrd_Grid_OnLButtonDblClk = function(type, row, colid, x, y) {
    try {
        if (colid === "ATTACH_FILE_NM") {
            const bzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
            const procsNo = dts_List.getCellData(row, "LIST_ELIGTY_PROCS_CD");
            let dtlSeq = dts_List.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ");
            const fileSeq = dts_List.getCellData(row, "ATTACH_FILE_SEQ");
            $c.elw.fn_filedown(bzProcsNo, procsNo, dtlSeq, fileSeq);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20506.mgrd_Grid_OnLButtonDblClk" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const arrCid = [{
        cid: "DELIST_REAL_INVSTG_RSN_CD",
        cnm: "cmb_DELIST_REAL_INVSTG_RSN_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "A^전체";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const fileContents = $c.stf.trim(txb_FileContents.getValue());
    if (fileContents.length > 0) {
        mgrd_Grid.show("");
        grd_Grid.hide();
    } else {
        mgrd_Grid.hide();
        grd_Grid.show("");
    }
    if (!$c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        return;
    }
    let vMarketTpCd = "";
    if (js_market === "1" || js_market === "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = rdo_MARKET_TP_CD.getValue();
    }
    let commitTpCd = "";
    if (js_market === "1") {
        commitTpCd = cmb_Commit_Tp_Cd_KOSPI.getValue();
    } else {
        commitTpCd = cmb_Commit_Tp_Cd.getValue();
    }
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/RealInvstg.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_List",
        action : "/RealInvstg.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 함수
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 함수
    arrPar[0] = txb_ISUR_CD.getValue();
    arrPar[1] = "";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].COM_NM);
        vIsurCd = arrPar[0].ISUR_CD;
    }
};

/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} procsNo procsNo
 * @param {*} dtlSeq dtlSeq
 * @param {*} fileSeq fileSeq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(bzProcsNo, procsNo, dtlSeq, fileSeq) {
    location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF20506.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + procsNo + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq + "&ATTACH_FILE_SEQ=" + fileSeq + "&gubun=42";
};
